(()=>{'use strict';
const STORAGE='cgu_atlas_affc_auditoria_v1';
const deepClone=x=>JSON.parse(JSON.stringify(x));
const seed=deepClone(window.CGU_SEED||{});
const questionBank=window.CGU_QUESTIONS||[];
const views={dashboard:'Visão geral',today:'Missão do dia',reviews:'Revisões SRS',quiz:'Questões C/E',tec:'Cadernos TEC',topics:'Edital & tópicos',calendar:'Calendário',difficulty:'Mapa de dificuldades',report:'Relatório semanal',settings:'Dados & ajustes'};
const $=s=>document.querySelector(s);
const esc=x=>String(x==null?'':x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeHref=x=>/^https:\/\//i.test(String(x||''))?esc(x):'#';
const n=x=>(Number(x)||0);
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
const pct=x=>`${Number(x).toLocaleString('pt-BR',{maximumFractionDigits:1})}%`;
const number=x=>n(x).toLocaleString('pt-BR');
const numeric=x=>String(n(x)).replace('.',',');
const nowDay=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const iso=d=>{const x=new Date(d+'T12:00:00');return isNaN(x)?nowDay():`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};
const advance=(d,days)=>{let dt=new Date((d||nowDay())+'T12:00:00');dt.setDate(dt.getDate()+days);return iso(`${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`)};
const dayDiff=(a,b)=>Math.round((new Date(a+'T12:00:00')-new Date(b+'T12:00:00'))/86400000);
const prettyDay=(d,extra={day:'2-digit',month:'short'})=>{try{return new Date(d+'T12:00:00').toLocaleDateString('pt-BR',extra)}catch(e){return d}};
const leftDays=()=>Math.max(0,dayDiff(state.exam||'2026-12-13',nowDay()));
function prunePrivateDocLinks(data){
  const walk=value=>{
    if(!value||typeof value!=='object')return;
    if(Array.isArray(value)){for(const item of value)walk(item);return}
    for(const [key,item] of Object.entries(value)){
      if(typeof item==='string'&&/^https?:\/\/(?:drive|docs)\.google\.com\//i.test(item))delete value[key];
      else if(item&&typeof item==='object')walk(item);
    }
  };
  walk(data);
  return data;
}
function loadFresh(){
  const fresh=prunePrivateDocLinks(deepClone(seed));
  for(const card of fresh.cards||[])if(!card.due)card.due=nowDay();
  return fresh;
}
function load(){try{let old=JSON.parse(localStorage.getItem(STORAGE)||'null');if(old&&old.app==='CGU Atlas'&&Array.isArray(old.books)&&Array.isArray(old.cards)){
  // Respect previously captured user records; enrich older versions with new seeded catalog entries.
  let existing=new Set(old.books.map(x=>x.code));for(let b of seed.books||[])if(!existing.has(b.code))old.books.push(deepClone(b));
  let oldTopic=new Set((old.topics||[]).map(x=>x.id));for(let t of seed.topics||[])if(!oldTopic.has(t.id))old.topics.push(deepClone(t));
  for(let key of ['batches','questionReviews','quizAttempts','writing','studyLogs','notes'])if(!Array.isArray(old[key]))old[key]=[];
  old.settings=Object.assign({},seed.settings,old.settings||{});
  return prunePrivateDocLinks(old);
 }}catch(e){console.warn('Não foi possível recuperar os dados',e)}return loadFresh()}
let state=load();
try{localStorage.setItem(STORAGE,JSON.stringify(state))}catch(e){/* armazenamento indisponível */}
let ui={view:'dashboard',tecFilter:'all',tecSearch:'',tecPage:0,tecSort:'relevant',topicFilter:'all',topicSearch:'',day:nowDay(),activeReview:null,revealed:false,quizBlock:'all',quizQuestion:null,quizAnswer:null,quizShow:false,quizDoubt:false,quizMode:'new',calendarWeek:'2026-11-15',reportDay:nowDay(),scatterHover:null};
const findTopic=id=>state.topics.find(x=>x.id===id);
const findBook=code=>state.books.find(x=>x.code===code);
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(state));return true}catch(e){console.warn('Falha no salvamento',e);toast('Armazenamento indisponível; exporte um backup.');return false}}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('visible'),3300)}
const weight=block=>block==='P3'?2:1;
const startedCount=()=>state.topics.filter(x=>x.status!=='not-started').length;
const studiedCount=()=>state.topics.filter(x=>x.status==='done').length;
const dueCards=()=>[...state.cards,...state.questionReviews].filter(x=>x.due&&x.due<=nowDay()).sort((a,b)=>a.due.localeCompare(b.due)||(a.lastRating==='again'?-1:1));
const reviewDue=()=>dueCards().length;
function batchScore(x){let w=weight(x.block);return {max:n(x.total)*w,net:(n(x.correct)-n(x.wrong))*w,accuracy:n(x.total)?n(x.correct)/n(x.total)*100:0,netRate:n(x.total)?(n(x.correct)-n(x.wrong))/n(x.total)*100:0}}
function bookStats(code){const all=state.batches.filter(b=>b.code===code&&b.mode==='nova');const total=all.reduce((s,x)=>s+n(x.total),0),correct=all.reduce((s,x)=>s+n(x.correct),0),wrong=all.reduce((s,x)=>s+n(x.wrong),0),blank=all.reduce((s,x)=>s+n(x.blank),0),doubt=all.reduce((s,x)=>s+n(x.doubt),0),min=all.reduce((s,x)=>s+n(x.minutes),0);let b=findBook(code);return {code,all,b,total,correct,wrong,blank,doubt,min,accuracy:total?100*correct/total:null,net:total?(correct-wrong)*weight(b?.block):null,netRate:total?100*(correct-wrong)/total:null,weakness:total?weight(b?.block)*(2*wrong+blank*.5+doubt)/total:null,low:total?((correct-wrong)/total<.5||doubt/total>=.25?'Crítico':((correct-wrong)/total<.75||doubt/total>.1?'Reforçar':'Manutenção')):'Sem dados'};}
const actualMinutes=()=>state.studyLogs.reduce((s,x)=>s+n(x.minutes),0)+state.batches.reduce((s,x)=>s+n(x.minutes),0);
const xp=()=>n(state.baseline?.xp)+state.quizAttempts.filter(x=>x.correct).reduce((s,x)=>s+10*weight(x.block),0)+state.questionReviews.reduce((s,x)=>s+(x.history||[]).filter(h=>h.rating==='easy').length*5,0)+state.cards.reduce((s,x)=>s+(x.history||[]).filter(h=>h.date!==(state.baseline?.cloze?.date||'')&&h.rating==='easy').length*5,0);
function getNextPlan(){return state.plan.find(p=>p.date>=nowDay()&&!p.done)||state.plan.find(p=>!p.done)||state.plan[0]}
function realSessions(){return state.batches.length+state.quizAttempts.length+state.studyLogs.length+state.writing.length}
const fmtTime=m=>`${Math.floor(n(m)/60)}h${String(n(m)%60).padStart(2,'0')}m`;
const tagBlock=b=>`<span class="tag ${esc((b||'').toLowerCase())}">${esc(b)}</span>`;
const miniLink=(url,label='Abrir ↗')=>url?`<a class="mini-link" href="${safeHref(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:'';
function heading(title,sub,actions='',eyebrow='CGU · MISSÃO AUDITORIA'){return `<div class="page-head"><div><span class="eyebrow">${eyebrow}</span><h1 class="page-title">${esc(title)}</h1><p class="page-sub">${sub}</p></div>${actions?`<div class="header-actions">${actions}</div>`:''}</div>`}
function boxEmpty(title,sub){return `<div class="empty"><strong>${esc(title)}</strong>${esc(sub)}</div>`}
function toggleNav(v){ui.view=v;ui.tecPage=0;ui.activeReview=null;ui.revealed=false;ui.quizShow=false;$('#sidebar').classList.remove('open');render();window.scrollTo(0,0)}
function updateTop(){document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===ui.view));$('#current-title').textContent=views[ui.view]||'Visão geral';$('#due-pill').textContent=reviewDue()||'';$('#daysleft').textContent=leftDays();$('#dayprogress').style.width=`${clamp(100*(29-leftDays())/29,0,100)}%`}
function render(){updateTop();let body='';try{body=({dashboard:renderDashboard,today:renderToday,reviews:renderReviews,quiz:renderQuiz,tec:renderTEC,topics:renderTopics,calendar:renderCalendar,difficulty:renderDifficulty,report:renderReport,settings:renderSettings}[ui.view]||renderDashboard)()}catch(e){console.error(e);body=`<div class="main"><div class="dangerline">Erro ao renderizar a seção. Os dados locais não foram apagados. ${esc(e.message)}</div></div>`}$('#app').innerHTML=body}
function renderDashboard(){const due=reviewDue(),batches=state.batches.filter(b=>b.mode==='nova'),studied=studiedCount(),total=state.topics.length,plan=getNextPlan(),ranked=state.books.map(x=>bookStats(x.code)).filter(x=>x.total>=5).sort((a,b)=>b.weakness-a.weakness).slice(0,4);const baseline=state.baseline?.diagnostic||null;const blockData=baseline?.blockScores?['P1','P2','P3'].filter(b=>Array.isArray(baseline.blockScores[b])).map(b=>({b,s:baseline.blockScores[b][0],max:baseline.blockScores[b][1]})):[];const thisWeek=state.plan.filter(x=>x.done).length;
return `<div class="main">${heading('Visão geral',`Seu centro de controle da CGU. ${prettyDay(nowDay(),{weekday:'long',day:'numeric',month:'long',year:'numeric'})}.`,`<button class="btn btn-ghost" data-view="report">▥ Relatório</button><button class="btn" data-view="today">Iniciar missão →</button>`)}
<div class="grid grid-4">
<div class="card metric"><span class="m-label">Nota diagnóstica Cebraspe</span><div class="m-ico">◎</div><div class="m-number">${baseline?baseline.net:"—"}${baseline?`<small style="font-size:15px;color:#9aa6b4"> / ${baseline.max}</small>`:""}</div><div class="m-note">${baseline?`${baseline.total} itens · ${baseline.correct} acertos · ${baseline.blank} omissões`:"Nenhum diagnóstico importado"}</div></div>
<div class="card metric"><span class="m-label">Revisões vencidas</span><div class="m-ico">↻</div><div class="m-number">${due}</div><div class="m-note">${due?'A fila prioriza falhas de evocação':'Nenhuma revisão atrasada'}</div></div>
<div class="card metric"><span class="m-label">Cobertura dos resumos</span><div class="m-ico">▦</div><div class="m-number">${studied}<small style="font-size:15px;color:#9aa6b4"> / ${total}</small></div><div class="m-note">Marcados como concluídos no aplicativo</div></div>
<div class="card metric card-dark"><span class="m-label">Experiência acumulada</span><div class="m-ico">✦</div><div class="m-number">${number(xp())} <small style="font-size:12px;color:#b3c7d2">XP</small></div><div class="m-note">Gamificação · não é nota de prova</div></div>
</div>
<div class="hero" style="margin:18px 0"><div><span class="eyebrow">PRÓXIMA MISSÃO RECOMENDADA</span><h2>${esc(plan?.title||'Iniciar revisão de conhecimentos')}</h2><p>${plan?.date?`Planejado para ${prettyDay(plan.date,{day:'2-digit',month:'long'})}`:''} · preparação dirigida · ${due} revisões vencidas</p></div><button class="btn" data-view="today">Abrir missão →</button><div class="hero-motif">⌁</div></div>
<div class="grid grid-70"><div class="stack">
<div class="card"><div class="card-head"><div><h3 class="card-title">Desempenho inicial por bloco</h3><p class="card-sub">Dados do diagnóstico individual, quando existentes neste navegador</p></div><span class="pill blue">Cebraspe</span></div>
<div style="display:grid;gap:17px">${blockData.map(x=>`<div><div class="between" style="margin-bottom:8px"><div class="flex">${tagBlock(x.b)} <span class="smalltext">${x.b==='P1'?'Básicos':x.b==='P2'?'Complementares':'Específicos'}</span></div><strong>${x.s} / ${x.max} pts</strong></div><div class="progress"><i style="width:${100*x.s/x.max}%;background:${x.b==='P3'?'#168f8b':x.b==='P2'?'#5477e8':'#8ea3b8'}"></i></div></div>`).join('')}</div>
<div class="info" style="margin-top:17px">P3 vale 2 pontos por item. Prova real: 40 itens P1 + 40 P2 + 90 P3; discursiva em duas questões (30 e 70 pontos).</div></div>
<div class="card"><div class="card-head"><div><h3 class="card-title">Mapa de domínio — resumos CGU</h3><p class="card-sub">${startedCount()} iniciados · ${studied} concluídos · ${total-startedCount()} não iniciados</p></div><button class="btn btn-ghost small" data-view="topics">Ver tópicos</button></div><div class="progress" style="height:11px"><i style="width:${total?100*studied/total:0}%"></i></div><p class="smalltext muted">Marque o avanço em cada tópico na tela Edital & tópicos. Itens do diagnóstico não são contados como cobertura concluída.</p><div class="chip-row">${['P1','P2','P3'].map(b=>{const x=state.topics.filter(t=>t.block===b);return `<span class="pill">${b}: ${x.filter(t=>t.status==='done').length}/${x.length} tópicos</span>`}).join('')}</div></div>
</div><div class="stack"><div class="card"><div class="card-head"><div><h3 class="card-title">Reforços prioritários</h3><p class="card-sub">Baseados nas revisões registradas</p></div><span class="pill amber">${reviewDue()} vencidas</span></div>
${dueCards().slice(0,3).map(x=>[x.topic||'Revisão',x.id,x.block||'CGU']).map(([t,id,b],i)=>`<div class="list-row"><span class="dot red"></span><div class="grow"><div class="row-title">${esc(t)}</div><div class="row-sub">${id} · ${b} · revisão programada</div></div><span class="pill red">D+1</span></div>`).join('')}
<button class="btn btn-light block" style="margin-top:15px" data-view="reviews">Revisar agora →</button></div>
<div class="card"><div class="card-head"><h3 class="card-title">Cadernos com maior dificuldade</h3><button data-view="tec" class="btn btn-ghost small">Todos</button></div>
${ranked.length?ranked.map(x=>`<div class="list-row"><span class="dot ${x.low==='Crítico'?'red':'amber'}"></span><div class="grow"><div class="row-title">${esc(x.code)} · ${esc(x.b.topic)}</div><div class="row-sub">${x.total} itens · ${pct(x.accuracy)} acertos · ${pct(x.netRate)} líquida</div></div><button class="btn btn-inline btn-ghost" data-action="open-book" data-code="${esc(x.code)}">Abrir</button></div>`).join(''):boxEmpty('Sem cadernos avaliados','Registre a primeira bateria TEC para começar o ranking real. O histórico Guruja fica separado.')}</div>
</div></div></div>`}
function renderToday(){const d=nowDay(),next=getNextPlan(),dayPlan=state.plan.find(p=>p.date===d),p=dayPlan||next,due=dueCards().slice(0,8);return `<div class="main">${heading('Missão do dia','Revisão ativa → conteúdo dirigido → questões → correção → registro.',`<button class="btn btn-ghost" data-view="calendar">Calendário</button><button class="btn btn-teal" data-view="reviews">${reviewDue()} revisões →</button>`)}
<div class="hero"><div><span class="eyebrow">ROTEIRO DINÂMICO</span><h2>${esc(p?.title||'Recuperar conceitos críticos')}</h2><p>${p?.date?`Plano ${prettyDay(p.date,{day:'2-digit',month:'long'})} · `:''}meta diária de ${n(state.settings.dailyMinutes)} minutos · prioridade no que ainda não está consolidado</p></div><button data-view="quiz" class="btn">Treinar questões →</button></div>
<div class="grid grid-70" style="margin-top:18px"><div class="stack">
<div class="card"><div class="card-head"><div><h3 class="card-title">Etapas de hoje</h3><p class="card-sub">Ajuste os blocos conforme o volume de revisões vencidas</p></div><span class="pill blue">3 h de referência</span></div><div class="daily-steps">
${[['01','Recuperação espaçada',`${reviewDue()} cartões vencidos; revisar por prioridade de prazo e dificuldade.`, 'reviews'],['02','Estudo dirigido',p?.title||'Escolher o próximo tópico prioritário','tec'],['03','Questões Cebraspe','Resolver itens inéditos autorais, C/E, um por vez.','quiz'],['04','Caderno TEC',p?.tec?`Caderno ${p.tec} — ${p.tecKind}`:'Sem caderno próprio nesta seção: usar questões internas.','tec'],['05','Registro e fechamento','Anotar tempo, acertos, dúvidas e próximos vencimentos.','today']].map(x=>`<div class="step"><div class="step-num">${x[0]}</div><div class="grow"><div class="row-title">${esc(x[1])}</div><div class="row-sub">${esc(x[2])}</div></div>${x[3]!=='today'?`<button class="btn btn-ghost small" data-view="${x[3]}">Abrir →</button>`:''}</div>`).join('')}</div></div>
<div class="card"><div class="card-head"><h3 class="card-title">Registrar tempo de estudo</h3><span class="pill">Não inclui tempo das baterias TEC já registrado</span></div><form id="study-form" class="form-grid"><div class="input-group"><label>Data</label><input required name="date" type="date" value="${d}"></div><div class="input-group"><label>Assunto</label><input required name="topic" placeholder="Ex.: diferenças em diferenças"></div><div class="input-group"><label>Minutos</label><input required name="minutes" type="number" min="1" max="900" placeholder="45"></div><div class="full form-actions"><button type="submit" class="btn btn-teal">Salvar estudo</button></div></form></div>
</div><div class="stack"><div class="card"><div class="card-head"><h3 class="card-title">Próximas revisões</h3><button class="btn btn-ghost small" data-view="reviews">Abrir fila</button></div>${due.length?due.map(x=>`<div class="list-row"><span class="dot ${x.lastRating==='again'?'red':'amber'}"></span><div class="grow"><div class="row-title">${esc(x.id)}</div><div class="row-sub">${esc(x.topic||x.code||'Questão TEC')} · ${prettyDay(x.due)} </div></div></div>`).join(''):boxEmpty('Nenhuma revisão pendente','As próximas datas serão exibidas após as respostas.')}</div>
<div class="card"><div class="card-head"><h3 class="card-title">Material da missão</h3></div><div class="list-row"><div class="grow"><div class="row-title">Resumo CGU</div><div class="row-sub">Fonte da seção do dia</div></div><span class="pill">Material privado não vinculado</span></div><div class="list-row"><div class="grow"><div class="row-title">Caderno TEC</div><div class="row-sub">${esc(p?.tecKind||'Não identificado')}</div></div>${p?.tecUrl?miniLink(p.tecUrl, p.tec+' ↗'):'<span class="pill amber">Sem caderno</span>'}</div></div></div></div></div>`}
function reviewCardHtml(x){let isTec=x.kind==='tec'||x.kind==='tec-batch';return `<div class="card"><div class="card-head"><div><h3 class="card-title">${esc(x.id)}</h3><p class="card-sub">${esc(x.topic||x.code||'Questão vinculada')} · ${esc(x.block||'')} · ${isTec?'Revisão de questão TEC':'Cartão interno'}</p></div><span class="pill ${x.lastRating==='again'?'red':'blue'}">${prettyDay(x.due)}</span></div>
<div class="flash-card"><span class="tagline">${isTec?'REFAZER A QUESTÃO EXTERNA':'RECUPERAÇÃO ATIVA · SEM CONSULTA'}</span><h3>${esc(x.front||`Refaça a questão ${x.questionId||''} do ${x.code||''}`)}</h3>${isTec?`<div>${miniLink(x.url||findBook(x.code)?.url,'Abrir caderno no TEC ↗')}</div>`:''}${ui.revealed?`<div class="answer">${isTec?'Marque seu resultado após resolver no TEC.':esc(x.back||'')}</div>${x.explain?`<div class="muted smalltext">${esc(x.explain)}</div>`:''}${x.source?`<div>${miniLink(x.source,'Consultar fonte após responder ↗')}</div>`:''}`:''}</div>
<div style="display:flex;gap:9px;flex-wrap:wrap;justify-content:center;margin-top:18px">${!ui.revealed?`<button class="btn btn-light" data-action="review-reveal">${isTec?'Já resolvi no TEC →':'Revelar resposta →'}</button>`:`<button class="btn btn-danger" data-action="review-grade" data-grade="again" data-id="${esc(x.id)}">Errei / não lembrei</button><button class="btn btn-ghost" data-action="review-grade" data-grade="hard" data-id="${esc(x.id)}">Acertei com dificuldade</button><button class="btn btn-teal" data-action="review-grade" data-grade="easy" data-id="${esc(x.id)}">Acertei facilmente</button>`}</div></div>`}
function renderReviews(){const due=dueCards();const active=ui.activeReview&&due.find(x=>x.id===ui.activeReview)||due[0];const upcoming=[...state.cards,...state.questionReviews].filter(x=>x.due>nowDay()).sort((a,b)=>a.due.localeCompare(b.due));const errors=[...state.cards,...state.questionReviews].filter(x=>x.lapses>0).length;
return `<div class="main">${heading('Revisões direcionadas','Fila adaptativa: falhas recentes → dúvidas → manutenção. Uma pergunta por vez.',`<button class="btn btn-ghost" data-view="tec">Cadernos TEC ↗</button>`)}
<div class="grid grid-3"><div class="card metric"><div class="m-label">Vencidas</div><div class="m-number">${due.length}</div><div class="m-note">Programadas até hoje</div></div><div class="card metric"><div class="m-label">Cartões em memória</div><div class="m-number">${state.cards.length+state.questionReviews.length}</div><div class="m-note">Cloze, C/E e questões TEC</div></div><div class="card metric"><div class="m-label">Com falha histórica</div><div class="m-number">${errors}</div><div class="m-note">Maior frequência de reaprendizagem</div></div></div>
<div class="grid grid-70" style="margin-top:17px"><div class="stack">${active?reviewCardHtml(active):`<div class="card">${boxEmpty('Revisões em dia','Todos os cartões vencidos foram tratados. Você pode praticar questões inéditas.') }<div style="margin-top:16px"><button class="btn btn-teal" data-view="quiz">Treinar questões novas →</button></div></div>`}<div class="card"><div class="card-head"><h3 class="card-title">Lógica de espaçamento</h3><span class="pill">Adaptativo</span></div><div class="grid grid-3"><div><div class="row-title red">Errei</div><div class="row-sub">Retorna em D+1</div></div><div><div class="row-title amber">Difícil</div><div class="row-sub">Revisão curta ≥D+2</div></div><div><div class="row-title green">Fácil</div><div class="row-sub">Amplia o intervalo ≥D+4</div></div></div><p class="smalltext muted">Os intervalos são operacionais, não um ajuste científico da sua curva individual de esquecimento. O prazo diminui após nova falha.</p></div></div>
<div class="stack"><div class="card"><div class="card-head"><h3 class="card-title">Fila de hoje</h3><span class="pill red">${due.length} pendentes</span></div>${due.length?due.slice(0,16).map(x=>`<div class="list-row"><span class="dot ${x.lastRating==='again'?'red':'blue'}"></span><div class="grow"><div class="row-title">${esc(x.id)}</div><div class="row-sub">${esc(x.topic||x.code||'Questões')} · ${prettyDay(x.due)}</div></div><button class="btn btn-ghost btn-inline" data-action="select-review" data-id="${esc(x.id)}">Abrir</button></div>`).join(''):boxEmpty('Fila zerada','As próximas revisões aparecem conforme seu histórico.')}</div>
<div class="card"><div class="card-head"><h3 class="card-title">Próximas revisões</h3></div>${upcoming.slice(0,8).map(x=>`<div class="list-row"><span class="dot"></span><div class="grow"><div class="row-title">${esc(x.id)}</div><div class="row-sub">${esc(x.topic||x.code||'Questão')}</div></div><span class="pill">${prettyDay(x.due)}</span></div>`).join('')||boxEmpty('Nenhuma próxima','Reforce os itens vencidos antes de agendar novos.')}</div></div></div></div>`}
function pickQuestion(){let pool=questionBank.filter(q=>ui.quizBlock==='all'||q.block===ui.quizBlock);if(ui.quizMode==='new'){let done=new Set(state.quizAttempts.map(x=>x.questionId));pool=pool.filter(x=>!done.has(x.id))}if(!pool.length)return null;const counts=Object.fromEntries(pool.map(x=>[x.id,state.quizAttempts.filter(a=>a.questionId===x.id).length]));pool.sort((a,b)=>counts[a.id]-counts[b.id]||(['P3','P2','P1'].indexOf(a.block)-['P3','P2','P1'].indexOf(b.block)));return pool[0]}
function renderQuiz(){if(!ui.quizQuestion||!questionBank.some(x=>x.id===ui.quizQuestion)){ui.quizQuestion=pickQuestion()?.id||null}const q=questionBank.find(x=>x.id===ui.quizQuestion);const recent=state.quizAttempts;let p3=recent.filter(x=>x.block==='P3');const totalNet=recent.reduce((s,x)=>s+(x.correct?weight(x.block):x.answer==='B'?0:-weight(x.block)),0);return `<div class="main">${heading('Questões C/E','Treino autoral para a CGU, uma assertiva por vez, com penalização Cebraspe.',`<button class="btn btn-ghost" data-view="reviews">↻ Revisar erros</button>`)}
<div class="grid grid-3"><div class="card metric"><div class="m-label">Itens respondidos no site</div><div class="m-number">${recent.length}</div><div class="m-note">Não inclui diagnóstico anterior</div></div><div class="card metric"><div class="m-label">Nota líquida acumulada</div><div class="m-number">${totalNet}</div><div class="m-note">P1/P2 ±1 · P3 ±2</div></div><div class="card metric"><div class="m-label">Taxa de acertos</div><div class="m-number">${recent.length?pct(100*recent.filter(x=>x.correct).length/recent.length):'—'}</div><div class="m-note">Exercícios novos deste site</div></div></div>
<div class="card" style="margin-top:16px"><div class="between" style="margin-bottom:17px"><div class="flex"><span class="tagline">MODO TREINO</span><span class="pill blue">${questionBank.length} questões disponíveis</span></div><div class="flex"><select id="quiz-block" aria-label="Filtrar bloco"><option value="all" ${ui.quizBlock==='all'?'selected':''}>Todos os blocos</option>${['P1','P2','P3'].map(b=>`<option ${ui.quizBlock===b?'selected':''}>${b}</option>`).join('')}</select><select id="quiz-mode" aria-label="Modo de seleção"><option value="new" ${ui.quizMode==='new'?'selected':''}>Não resolvidas</option><option value="mixed" ${ui.quizMode==='mixed'?'selected':''}>Prática geral</option></select></div></div>
${q?`<div class="flash-card" style="text-align:left"><div class="between"><div class="flex">${tagBlock(q.block)}<span class="pill">${esc(q.topic)}</span></div><span class="pill">${esc(q.id)} · ${weight(q.block)>1?'±2':'±1'}</span></div><h3 style="text-align:left;margin:10px 0">${esc(q.q)}</h3><div class="smalltext muted">Questão inédita autoral · Sem gabarito antecipado</div></div>
<div style="margin-top:16px">${ui.quizShow?`<div class="feedback ${ui.quizAnswer===q.a?'correct':'wrong'}"><strong>Gabarito: ${q.a==='C'?'Certo':'Errado'}.</strong> ${esc(q.why)}<p class="smalltext muted">Resposta registrada: ${ui.quizAnswer==='B'?'Em branco':ui.quizAnswer==='C'?'Certo':'Errado'}${ui.quizDoubt?' · baixa confiança':''}. ${ui.quizAnswer===q.a?'Acerto':'Revisão programada'}.</p></div><div class="form-actions" style="margin-top:15px"><button class="btn btn-teal" data-action="quiz-next">Próxima questão →</button></div>`:`<div class="choices" style="margin-top:19px">${[['C','Certo'],['E','Errado'],['B','Em branco']].map(v=>`<button class="choice ${ui.quizAnswer===v[0]?'selected':''}" data-action="quiz-choose" data-answer="${v[0]}">${v[1]}</button>`).join('')}</div><div class="between" style="margin-top:20px;flex-wrap:wrap"><label class="smalltext muted"><input id="quiz-doubt" type="checkbox" ${ui.quizDoubt?'checked':''}> Marcar como dúvida</label><button class="btn" data-action="quiz-submit" ${!ui.quizAnswer?'disabled':''}>Confirmar resposta</button></div>`}</div>`:boxEmpty('Banco concluído','Altere o filtro para Prática geral e refaça questões, ou abra a fila de revisões.')}
</div></div>`}
function renderTEC(){let stats=state.books.map(x=>bookStats(x.code));let f=ui.tecFilter;if(f!=='all')stats=stats.filter(x=>x.b.block===f);if(ui.tecSearch){let q=ui.tecSearch.toLowerCase();stats=stats.filter(x=>(x.code+' '+x.b.area+' '+x.b.topic).toLowerCase().includes(q))}if(ui.tecSort==='worst')stats.sort((a,b)=>(b.total?1:0)-(a.total?1:0)||n(b.weakness)-n(a.weakness));else if(ui.tecSort==='best')stats.sort((a,b)=>(b.total?1:0)-(a.total?1:0)||n(a.weakness)-n(b.weakness));else stats.sort((a,b)=>{let aa=state.plan.find(p=>p.tec===a.code)?.date||'9999',bb=state.plan.find(p=>p.tec===b.code)?.date||'9999';return aa.localeCompare(bb)||(['P3','P2','P1'].indexOf(a.b.block)-['P3','P2','P1'].indexOf(b.b.block))});const cnt=stats.length;const start=ui.tecPage*15;stats=stats.slice(start,start+15);let batches=state.batches.slice().reverse().slice(0,8);const completed=state.batches.filter(x=>x.mode==='nova').length;const worst=state.books.map(x=>bookStats(x.code)).filter(x=>x.total>=10).sort((a,b)=>b.weakness-a.weakness);
return `<div class="main">${heading('Cadernos TEC','Catálogo extraído dos resumos da pasta CGU; registre suas baterias e programe erradas/dúvidas.',`<button class="btn btn-ghost" data-action="tec-paste">⇢ Colar resultado</button><button class="btn" data-action="open-book" data-code="${esc(state.plan.find(p=>p.tec)?.tec||state.books[0].code)}">+ Registrar caderno</button>`)}
<div class="grid grid-4"><div class="card metric"><div class="m-label">Cadernos catalogados</div><div class="m-number">${state.books.length}</div><div class="m-note">${state.topics.length} tópicos do edital</div></div><div class="card metric"><div class="m-label">Baterias novas registradas</div><div class="m-number">${completed}</div><div class="m-note">Sem misturar refazer questões</div></div><div class="card metric"><div class="m-label">Questões TEC resolvidas</div><div class="m-number">${number(state.batches.filter(x=>x.mode==='nova').reduce((s,x)=>s+n(x.total),0))}</div><div class="m-note">Somente resultados enviados por você</div></div><div class="card metric card-dark"><div class="m-label">Questões TEC em revisão</div><div class="m-number">${state.questionReviews.length}</div><div class="m-note">Por ID quando informado</div></div></div>
<div class="card" style="margin-top:17px"><div class="between" style="margin-bottom:17px;flex-wrap:wrap"><div><h3 class="card-title">Biblioteca de cadernos</h3><p class="card-sub">${cnt} encontrados · prioridade para os vinculados à missão da semana</p></div><span class="pill amber">Classificação só após registrar desempenho real</span></div>
<div class="filterbar"><input id="tec-search" aria-label="Pesquisar cadernos" placeholder="Buscar por código, área ou tópico" value="${esc(ui.tecSearch)}"><select id="tec-block" aria-label="Filtrar bloco"><option value="all">Todos os blocos</option>${['P1','P2','P3'].map(b=>`<option value="${b}" ${ui.tecFilter===b?'selected':''}>${b}</option>`).join('')}</select><select id="tec-sort" aria-label="Ordenar cadernos"><option value="relevant" ${ui.tecSort==='relevant'?'selected':''}>Plano da semana</option><option value="worst" ${ui.tecSort==='worst'?'selected':''}>Piores primeiro</option><option value="best" ${ui.tecSort==='best'?'selected':''}>Melhores primeiro</option></select></div>
<div class="table-scroll"><table><thead><tr><th>Caderno</th><th>Bloco / Área</th><th>Tópico vinculado</th><th>Questões</th><th>Acerto</th><th>Líquida</th><th>Prioridade</th><th></th></tr></thead><tbody>${stats.map(x=>`<tr><td><span class="tec-code">${esc(x.code)}</span><div>${miniLink(x.b.url,'Abrir TEC ↗')}</div></td><td>${tagBlock(x.b.block)} <div class="smalltext muted">${esc(x.b.area)}</div></td><td>${esc(x.b.topic)}</td><td>${x.total||'—'}</td><td>${x.total?pct(x.accuracy):'—'}</td><td>${x.total?pct(x.netRate):'—'}</td><td><span class="pill ${x.low==='Crítico'?'red':x.low==='Reforçar'?'amber':x.low==='Manutenção'?'green':''}">${esc(x.low)}</span></td><td><button class="btn btn-ghost btn-inline" data-action="open-book" data-code="${esc(x.code)}">Registrar</button></td></tr>`).join('')}</tbody></table></div>
<div class="between" style="margin-top:12px"><span class="smalltext muted">Exibindo ${Math.min(start+1,cnt)}–${Math.min(start+15,cnt)} de ${cnt}</span><div class="flex"><button class="btn btn-ghost small" data-action="tec-page" data-page="${ui.tecPage-1}" ${ui.tecPage===0?'disabled':''}>← Anterior</button><button class="btn btn-ghost small" data-action="tec-page" data-page="${ui.tecPage+1}" ${start+15>=cnt?'disabled':''}>Próximo →</button></div></div></div>
<div class="grid grid-2" style="margin-top:17px"><div class="card"><div class="card-head"><h3 class="card-title">Desempenhos que exigem atenção</h3><span class="pill red">Amostra ≥10</span></div>${worst.length?worst.slice(0,5).map(x=>`<div class="list-row"><span class="dot ${x.low==='Crítico'?'red':'amber'}"></span><div class="grow"><div class="row-title">${esc(x.code)} — ${esc(x.b.topic)}</div><div class="row-sub">${x.total} itens · ${pct(x.netRate)} de nota líquida · ${x.doubt} dúvidas</div></div><button class="btn btn-ghost small" data-action="open-book" data-code="${esc(x.code)}">Refazer</button></div>`).join(''):boxEmpty('Nenhum caderno avaliado','O ranking será gerado a partir dos resultados de baterias com pelo menos 10 itens.')}</div>
<div class="card"><div class="card-head"><h3 class="card-title">Últimos lançamentos</h3></div>${batches.length?batches.map(x=>`<div class="list-row"><span class="dot blue"></span><div class="grow"><div class="row-title">${esc(x.code)} · ${x.total} itens</div><div class="row-sub">${prettyDay(x.date)} · ${x.correct} acertos · ${x.wrong} erros · ${x.blank} brancos · ${x.doubt} dúvidas</div></div><span class="pill">${batchScore(x).net} pts</span></div>`).join(''):boxEmpty('Sem registros TEC','Registre sua primeira bateria, com ou sem os IDs das questões.')}</div></div></div>`}
function renderTopics(){let list=state.topics.filter(x=>ui.topicFilter==='all'||x.block===ui.topicFilter);if(ui.topicSearch){const q=ui.topicSearch.toLowerCase();list=list.filter(x=>(x.area+' '+x.name+' '+x.id).toLowerCase().includes(q))}const nDone=list.filter(x=>x.status==='done').length;return `<div class="main">${heading('Edital e mapa de tópicos','81 resumos do Drive, seus cadernos TEC e o estágio de cobertura de cada assunto.',`<button class="btn btn-ghost" data-view="tec">Ver cadernos TEC →</button>`)}
<div class="grid grid-3"><div class="card metric"><div class="m-label">Tópicos visíveis</div><div class="m-number">${list.length}</div><div class="m-note">Edital CGU AFFC Auditoria</div></div><div class="card metric"><div class="m-label">Concluídos</div><div class="m-number">${nDone}</div><div class="m-note">Marcados manualmente por você</div></div><div class="card metric"><div class="m-label">Em progresso</div><div class="m-number">${list.filter(x=>x.status==='in-progress').length}</div><div class="m-note">Cobertura registrada neste sistema</div></div></div>
<div class="card" style="margin-top:17px"><div class="card-head"><div><h3 class="card-title">Biblioteca do edital</h3><p class="card-sub">Clique no estado para mudar: Não iniciado → Em andamento → Concluído → Não iniciado.</p></div></div><div class="filterbar"><input id="topic-search" placeholder="Pesquisar tópico ou área" value="${esc(ui.topicSearch)}"><select id="topic-block"><option value="all">Todos os blocos</option>${['P1','P2','P3'].map(b=>`<option value="${b}" ${ui.topicFilter===b?'selected':''}>${b}</option>`).join('')}</select></div>
<div class="table-scroll"><table><thead><tr><th>ID</th><th>Bloco</th><th>Área</th><th>Tópico</th><th>Material</th><th>Cadernos do TEC</th><th>Etapa</th></tr></thead><tbody>${list.map(t=>`<tr><td class="tec-code">${esc(t.id)}</td><td>${tagBlock(t.block)}</td><td>${esc(t.area)}</td><td class="table-bold">${esc(t.name)}</td><td><span class="smalltext muted">Consulta particular</span></td><td>${t.tecCodes.length?t.tecCodes.map(code=>miniLink(findBook(code)?.url||`https://www.tecconcursos.com.br/s/${code}`,code+' ↗')).join(', '):'<span class="pill amber">Sem caderno específico</span>'}</td><td><button class="btn btn-inline ${t.status==='done'?'btn-teal':'btn-ghost'}" data-action="topic-status" data-id="${esc(t.id)}">${t.status==='done'?'Concluído ✓':t.status==='in-progress'?'Em andamento':'Não iniciado'}</button></td></tr>`).join('')}</tbody></table></div></div></div>`}
function renderCalendar(){const today=nowDay(),plan=state.plan.slice().sort((a,b)=>a.date.localeCompare(b.date));const pDay=ui.calendarWeek||today;let w=plan.filter(x=>x.date>=pDay).slice(0,7);if(!w.length)w=plan;const total=plan.length,complete=plan.filter(x=>x.done).length;return `<div class="main">${heading('Calendário inteligente','Sua semana é flexível. Reprograme tarefas sem perder o histórico, priorizando revisões vencidas.',`<button class="btn btn-ghost" data-view="today">Minha missão →</button>`)}
<div class="grid grid-3"><div class="card metric"><div class="m-label">Tarefas concluídas</div><div class="m-number">${complete}/${total}</div><div class="m-note">Na janela de planejamento atual</div></div><div class="card metric"><div class="m-label">Carga semanal prevista</div><div class="m-number">${state.settings.weekHours} h</div><div class="m-note">Adaptável à disponibilidade real</div></div><div class="card metric"><div class="m-label">Tempo registrado</div><div class="m-number">${fmtTime(actualMinutes())}</div><div class="m-note">Tempo adicional + baterias TEC</div></div></div>
<div class="card" style="margin-top:16px"><div class="card-head"><div><h3 class="card-title">Plano 15 a 21 de novembro</h3><p class="card-sub">Base do diagnóstico CGU; ajustes de tarefas e datas são salvos neste navegador</p></div><span class="pill blue">${Math.round(complete/Math.max(1,total)*100)}% concluído</span></div><div class="calendar-grid">${plan.map(p=>`<div class="day-card ${p.date===today?'today':''} ${p.done?'done':''}"><div class="day-header"><span class="dayname">${prettyDay(p.date,{weekday:'short'})}</span><span class="pill ${p.done?'green':'blue'}">${p.done?'Feito':tagBlock(p.block)}</span></div><div class="day-date">${prettyDay(p.date,{day:'numeric',month:'short'})}</div><div class="day-topic">${esc(p.title)}</div><div class="day-min">${Number(p.srs)+Number(p.theory)+Number(p.questions)+Number(p.writing)+Number(p.correction)} min planejados ${p.actualMinutes?'· '+p.actualMinutes+' realizados':''}</div><div class="day-footer"><button class="btn btn-ghost small" data-action="calendar-edit" data-id="${esc(p.id)}">${p.done?'Editar ✓':'Editar missão'}</button></div></div>`).join('')}</div></div>
<div class="grid grid-2" style="margin-top:16px"><div class="card"><div class="card-head"><h3 class="card-title">Como o planejamento se adapta</h3></div><div class="daily-steps"><div class="step"><div class="step-num">1</div><div><strong>Revisões vencidas primeiro.</strong><div class="row-sub">O volume real da fila desloca o tempo de novos conteúdos.</div></div></div><div class="step"><div class="step-num">2</div><div><strong>Cadernos com pior desempenho.</strong><div class="row-sub">Erros e dúvidas retornam em sessões futuras de forma espaçada.</div></div></div><div class="step"><div class="step-num">3</div><div><strong>Preservar os três blocos.</strong><div class="row-sub">P3 recebe prioridade, sem abandonar os mínimos de P1/P2.</div></div></div></div></div><div class="card"><div class="card-head"><h3 class="card-title">Prova e marco de revisão</h3></div><div class="kpi-meter"><div class="ring" style="--deg:${clamp(100*(29-leftDays())/29,0,100)}%"><span>${leftDays()}</span></div><div><div class="row-title">Dias até 13/12/2026</div><p class="row-sub">Objetiva: 170 itens e 260 pontos; discursiva: duas questões (100 pontos). Calendário pode ser alterado se houver nova retificação oficial.</p></div></div><div class="divider"></div>${miniLink('https://www.cebraspe.org.br/concursos/CGU_26_AFFC','Consultar edital e retificações ↗')}</div></div></div>`}
function scatterPlot(){const groups={};for(let b of state.batches){if(b.mode!=='nova')continue;let key=b.code;let o=groups[key]||{code:key,correct:0,tot:0,min:0,wrong:0};o.correct+=n(b.correct);o.wrong+=n(b.wrong);o.tot+=n(b.total);o.min+=n(b.minutes);groups[key]=o}let pts=Object.values(groups).filter(x=>x.tot>=3&&x.min>0).map(x=>({...x,acc:100*x.correct/x.tot,topic:findBook(x.code)?.topic||x.code}));if(!pts.length)return boxEmpty('Mapa ainda não calibrado','Registre baterias TEC com total, acertos e tempo para visualizar tempo gasto × taxa de acerto. Não usamos tempo inventado a partir do Guruja.');const maxT=Math.max(30,...pts.map(x=>x.min))*1.13;const toX=x=>55+(x/maxT)*650,toY=y=>278-(y/100)*235;let svg=`<svg viewBox="0 0 760 315" class="scatter" role="img" aria-label="Mapa de dificuldades por tempo e precisão"><line x1="55" x2="710" y1="278" y2="278" stroke="#bdc8d6"/><line x1="55" x2="55" y1="43" y2="278" stroke="#bdc8d6"/>`;for(let i=0;i<=4;i++){let v=i*25,y=toY(v);svg+=`<line x1="55" x2="710" y1="${y}" y2="${y}" stroke="#e8edf3"/><text x="43" y="${y+4}" font-size="11" fill="#8495a7" text-anchor="end">${v}%</text>`}for(let i=0;i<=4;i++){let v=maxT*i/4,x=toX(v);svg+=`<text x="${x}" y="299" text-anchor="middle" font-size="11" fill="#8495a7">${Math.round(v)}</text>`}svg+=`<text x="380" y="312" text-anchor="middle" font-size="11" fill="#8a97a9">Tempo registrado (min)</text>`;for(let x of pts){let xx=toX(x.min),yy=toY(x.acc),col=x.acc<60?'#d45e68':x.acc<75?'#edb35a':'#24ad9e';svg+=`<circle cx="${xx}" cy="${yy}" r="${Math.min(17,7+x.tot/7)}" fill="${col}" opacity=".78" stroke="white" stroke-width="3"><title>${esc(x.code)} · ${esc(x.topic)} · ${pct(x.acc)} · ${x.min} min · ${x.tot} itens</title></circle>`}svg+='</svg>';return svg}
function renderDifficulty(){const ranked=state.books.map(x=>bookStats(x.code)).filter(x=>x.total>=10).sort((a,b)=>b.weakness-a.weakness);const historic=state.guruja||[];const priority=[['P3','Políticas públicas e avaliação causal','Treinar contrafactual e métodos quase experimentais'],['P2','Processo administrativo e garantias','Treinar distinções procedimentais e hipóteses de defesa'],['P3','AFO e contabilidade pública','Treinar classificação orçamentária, VPD e demonstrações'],['P3','Amostragem e achados','Treinar amostragem, evidências e critérios'],['P3','Integridade e responsabilização','Treinar Lei 12.846/2013 e aplicação a casos']];return `<div class="main">${heading('Mapa de dificuldades','Cruza tempo registrado, precisão e penalização; trata o histórico Guruja como referência externa.',`<button class="btn btn-ghost" data-view="tec">Registrar no TEC →</button>`)}
<div class="grid grid-70"><div class="stack"><div class="card"><div class="card-head"><div><h3 class="card-title">Mapa tempo × acurácia</h3><p class="card-sub">Cada ponto representa um caderno TEC com tempo informado</p></div></div>${scatterPlot()}<div class="legend" style="margin-top:11px"><span class="flex"><span class="dot red"></span> Acurácia &lt;60%</span><span class="flex"><span class="dot amber"></span> 60%–74,9%</span><span class="flex"><span class="dot"></span> ≥75%</span></div></div>
<div class="card"><div class="card-head"><div><h3 class="card-title">Ranking dos cadernos avaliados</h3><p class="card-sub">Maior risco em primeiro lugar · mínimo de 10 questões</p></div></div>${ranked.length?`<div class="table-scroll"><table><thead><tr><th>TEC</th><th>Questões</th><th>Acerto</th><th>Nota líquida %</th><th>Dúvidas</th><th>Situação</th></tr></thead><tbody>${ranked.map(x=>`<tr><td class="tec-code">${esc(x.code)}</td><td>${x.total}</td><td>${pct(x.accuracy)}</td><td>${pct(x.netRate)}</td><td>${x.doubt}</td><td><span class="pill ${x.low==='Crítico'?'red':x.low==='Reforçar'?'amber':'green'}">${x.low}</span></td></tr>`).join('')}</tbody></table></div>`:boxEmpty('Sem dados reais do TEC','Os cadernos do Drive já estão vinculados, mas ainda aguardam os primeiros resultados.')}</div></div>
<div class="stack"><div class="card"><div class="card-head"><h3 class="card-title">Ordem de intervenção</h3><span class="pill amber">Provisória</span></div>${priority.map((p,i)=>`<div class="priority"><span class="rank">${i+1}</span><div class="grow"><div class="row-title">${esc(p[1])}</div><div class="row-sub">${esc(p[2])}</div></div>${tagBlock(p[0])}</div>`).join('')}<div class="info" style="margin-top:13px">A ordem é um roteiro temático provisório e deve ser adaptada aos resultados registrados localmente. Não é um gráfico de Pareto de incidência do Cebraspe, pois não dispomos de frequência de cobrança por tópico.</div></div>
<div class="card"><div class="card-head"><h3 class="card-title">Referência histórica — Guruja</h3><span class="pill">Outra grade, não CGU</span></div>${historic.map(x=>`<div style="margin-bottom:13px"><div class="between" style="margin-bottom:4px"><span class="smalltext">${esc(x.label)}</span><span class="smalltext strong">${pct(x.accuracy)} <span class="muted">/ ${x.count} itens</span></span></div><div class="progress"><i style="width:${x.accuracy}%;background:${x.accuracy<67?'#de8674':x.accuracy<75?'#edb96a':'#55aa9f'}"></i></div></div>`).join('')}<p class="tiny muted">Não confundir percentuais de outra grade com desempenho no edital CGU 2026.</p></div></div></div></div>`}
function weeklyStats(day){let start=advance(day,-6);let included=b=>b.date>=start&&b.date<=day;const batches=state.batches.filter(included),quiz=state.quizAttempts.filter(included),study=state.studyLogs.filter(included),w=state.writing.filter(included);let merged=[...batches.filter(b=>b.mode==='nova')];let total=merged.reduce((s,x)=>s+x.total,0)+quiz.length,correct=merged.reduce((s,x)=>s+x.correct,0)+quiz.filter(x=>x.correct).length,wrong=merged.reduce((s,x)=>s+x.wrong,0)+quiz.filter(x=>x.answer!=='B'&&!x.correct).length,blank=merged.reduce((s,x)=>s+x.blank,0)+quiz.filter(x=>x.answer==='B').length,uncertain=merged.reduce((s,x)=>s+x.doubt,0)+quiz.filter(x=>x.doubt).length;let minutes=batches.reduce((s,x)=>s+x.minutes,0)+study.reduce((s,x)=>s+x.minutes,0);let net=merged.reduce((s,x)=>s+batchScore(x).net,0)+quiz.reduce((s,x)=>s+(x.correct?weight(x.block):x.answer==='B'?0:-weight(x.block)),0);const groups={};for(let x of merged){let g=groups[x.code]||{code:x.code,total:0,correct:0,wrong:0,doubt:0};g.total+=x.total;g.correct+=x.correct;g.wrong+=x.wrong;g.doubt+=x.doubt;groups[x.code]=g}let worst=Object.values(groups).filter(x=>x.total>=5).sort((a,b)=>(a.correct-a.wrong)/a.total-(b.correct-b.wrong)/b.total).slice(0,3);let flagged=state.questionReviews.filter(x=>(x.history||[]).some(h=>included(h)));return {start,day,batches,quiz,study,w,total,correct,wrong,blank,uncertain,minutes,net,worst,flagged}}
function makeReportHtml(r){return `<div class="report"><span class="eyebrow">RELATÓRIO AUTOMÁTICO · ${prettyDay(r.start)} A ${prettyDay(r.day)}</span><h3>O que o seu desempenho mostra</h3><p>${r.total?`Você respondeu <b>${r.total}</b> itens novos nesta janela, com <b>${r.correct}</b> acertos, <b>${r.wrong}</b> erros e <b>${r.blank}</b> omissões. A nota líquida conjunta foi <b>${r.net}</b> pontos ponderados por bloco.`:'Ainda não há baterias novas nem questões internas registradas nesta janela.'} O tempo adicional registrado no sistema totalizou <b>${fmtTime(r.minutes)}</b>.</p>
${state.baseline?.diagnostic?.date>=r.start&&state.baseline?.diagnostic?.date<=r.day?`<p>Diagnóstico armazenado localmente: <b>${state.baseline.diagnostic.net}/${state.baseline.diagnostic.max}</b> pontos. Os indicadores importados não são somados às baterias novas.</p>`:''}
<h3>Onde intervir</h3>${r.worst.length?`<ul>${r.worst.map(x=>`<li><b>TEC ${esc(x.code)}</b>: ${x.correct}/${x.total} acertos, ${x.wrong} erros, ${x.doubt} dúvidas. Refaça os IDs problemáticos e teste nova bateria após as revisões.</li>`).join('')}</ul>`:`<p>Sem ranking confiável de cadernos nesta janela. O foco permanece em <b>avaliação causal</b>, <b>processo sancionador</b>, <b>AFO/CASP</b> e <b>amostragem de auditoria</b>.</p>`}
<h3>Próximos passos recomendados</h3><ul><li>Executar os cartões vencidos antes de adicionar novas questões.</li><li>Priorizar lotes de 10–20 questões dos cadernos relevantes da semana, registrando erros e dúvidas por ID.</li><li>Reexaminar as questões erradas e as respondidas com baixa confiança após D+1 e espaçar conforme a recuperação.</li><li>Reservar treino de situação-problema discursiva P3 e proteção dos mínimos de P1/P2.</li></ul><div class="report-note"><b>Como interpretar:</b> este texto é gerado automaticamente a partir dos registros locais; não representa mentoria humana, posição na concorrência ou validação estatística de aprovação.</div></div>`}
function renderReport(){let r=weeklyStats(ui.reportDay);return `<div class="main">${heading('Relatório semanal individual','Síntese automática baseada no seu histórico, com recomendações de ação por evidência.',`<button class="btn btn-ghost" data-action="report-download">⇩ Exportar TXT</button><button class="btn" data-action="copy-chat">Copiar resumo para ChatGPT</button>`)}<div class="card" style="margin-bottom:16px"><div class="selector-row"><div><h3 class="card-title">Janela de análise: últimos 7 dias</h3><p class="card-sub">Escolha o último dia do período</p></div><input style="width:190px" type="date" id="report-date" value="${esc(ui.reportDay)}"></div></div><div class="grid grid-4" style="margin-bottom:17px"><div class="card metric"><div class="m-label">Novas questões</div><div class="m-number">${r.total}</div><div class="m-note">Inclui TEC e quiz interno</div></div><div class="card metric"><div class="m-label">Acertos</div><div class="m-number">${r.correct}</div><div class="m-note">${r.total?pct(100*r.correct/r.total):'Sem amostra'}</div></div><div class="card metric"><div class="m-label">Erros + omissões</div><div class="m-number">${r.wrong+r.blank}</div><div class="m-note">${r.uncertain} dúvidas informadas</div></div><div class="card metric"><div class="m-label">Tempo registrado</div><div class="m-number">${fmtTime(r.minutes)}</div><div class="m-note">Não estima horas externas</div></div></div>${makeReportHtml(r)}</div>`}
function renderSettings(){let size='—';try{size=(new Blob([JSON.stringify(state)]).size/1024).toFixed(1)+' KB'}catch(e){}return `<div class="main">${heading('Dados & ajustes','Seus registros são armazenados neste navegador. Faça cópias periódicas para não perder sua evolução.',`<button class="btn" data-action="export">⇩ Exportar backup JSON</button>`)}
<div class="grid grid-63"><div class="stack"><div class="card"><div class="card-head"><h3 class="card-title">Disponibilidade e rotina</h3></div><form id="settings-form" class="form-grid two"><div class="input-group"><label>Minutos de estudo por dia</label><input name="daily" type="number" min="20" max="900" value="${n(state.settings.dailyMinutes)}" required></div><div class="input-group"><label>Horas disponíveis por semana</label><input name="weekly" type="number" min="1" max="90" value="${n(state.settings.weekHours)}" required></div><div class="full form-actions"><button class="btn btn-teal" type="submit">Salvar ajustes</button></div></form></div>
<div class="card"><div class="card-head"><h3 class="card-title">Backup e restauração</h3></div><div class="step"><span class="step-num">⇩</span><div class="grow"><div class="row-title">Exportar tudo</div><div class="row-sub">Inclui respostas, cadernos, questões com dúvida, revisões e calendário.</div></div><button class="btn btn-ghost small" data-action="export">Exportar</button></div><div class="step" style="margin-top:9px"><span class="step-num">⇧</span><div class="grow"><div class="row-title">Importar backup JSON</div><div class="row-sub">Substitui o estado atual após confirmação.</div></div><button class="btn btn-ghost small" data-action="import">Importar</button></div><div class="step" style="margin-top:9px"><span class="step-num">↻</span><div class="grow"><div class="row-title">Restaurar dados iniciais</div><div class="row-sub">Apaga dados locais adicionados após a configuração. Exige confirmação.</div></div><button class="btn btn-danger small" data-action="reset">Restaurar</button></div></div>
<div class="card"><div class="card-head"><h3 class="card-title">Integração com ChatGPT</h3></div><div class="info">Este aplicativo <b>não</b> acessa automaticamente a sua conta TEC, o ChatGPT, o Google Drive nem o Guruja. Depois de registrar uma bateria, você pode copiar o resumo gerado e colá-lo no seu Projeto CGU no ChatGPT. O registro no site é imediato; a sincronização externa exige uma integração autorizada, ainda não implementada.</div><div class="form-actions" style="margin-top:12px"><button class="btn btn-ghost" data-action="copy-chat">Copiar histórico resumido</button><button class="btn btn-ghost" data-action="export">Exportar JSON para análise</button></div></div></div>
<div class="stack"><div class="card"><div class="card-head"><h3 class="card-title">Inventário da aplicação</h3></div>${[['Tópicos do edital',state.topics.length],['Cadernos TEC',state.books.length],['Cartões SRS',state.cards.length],['Revisões de questões TEC',state.questionReviews.length],['Baterias registradas',state.batches.length],['Questões internas respondidas',state.quizAttempts.length],['Tamanho dos dados',size]].map(([a,b])=>`<div class="list-row"><span class="smalltext muted">${esc(a)}</span><strong class="smalltext">${esc(b)}</strong></div>`).join('')}</div>
<div class="card"><h3 class="card-title">Fontes e limites</h3><p class="smalltext muted">A estrutura usa os títulos dos 81 resumos e as referências a cadernos do TEC disponíveis na pasta fornecida. Os PDFs privados não são publicados nem vinculados nesta versão.</p><div class="list-row"><span class="smalltext">Edital CGU 2026</span>${miniLink('https://www.cebraspe.org.br/concursos/CGU_26_AFFC')}</div><div class="list-row"><span class="smalltext">Site de referência funcional</span>${miniLink('https://www.centurio.com.br/','Centurio ↗')}</div><p class="smalltext muted">Sem dados de concorrentes, frequência real de incidência por tópico ou correção oficial automática. Não é uma reprodução, extensão ou produto afiliado ao Centurio.</p></div></div></div></div>`}
function modal(html){$('#modal-root').innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-label="Detalhes da atividade">${html}</div>`;$('#modal-root').scrollTop=0}
function closeModal(){$('#modal-root').innerHTML=''}
function openBookForm(code){let b=findBook(code)||state.books[0];let topic=findTopic(b.topicIds[0]);modal(`<div class="modal-head"><div><span class="eyebrow">TEC · LANÇAMENTO DE BATERIA</span><h2>${esc(b.code)} · ${esc(b.topic)}</h2><p class="page-sub">${esc(b.block)} · ${esc(b.area)} · ${miniLink(b.url,'Abrir o caderno no TEC ↗')}</p></div><button class="close" data-action="close-modal" aria-label="Fechar">×</button></div>
<div class="info" style="margin-bottom:17px">Informe o resultado real após resolver no TEC. IDs de erradas e dúvidas permitem revisões individualizadas; sem IDs o sistema programa uma retomada geral do lote.</div>
<form id="tec-form" class="form-grid three">
<div class="input-group"><label>Caderno</label><select name="code" required id="batch-code">${state.books.map(x=>`<option value="${esc(x.code)}" ${x.code===b.code?'selected':''}>${esc(x.code)} · ${esc(x.topic).slice(0,45)}</option>`).join('')}</select></div>
<div class="input-group"><label>Data da sessão</label><input name="date" type="date" value="${nowDay()}" required></div>
<div class="input-group"><label>Tipo</label><select name="mode"><option value="nova">Nova bateria</option><option value="redo">Refazer erradas/dúvidas</option></select></div>
<div class="input-group"><label>Questões resolvidas</label><input name="total" type="number" min="1" max="1000" value="20" required></div>
<div class="input-group"><label>Acertos (C)</label><input name="correct" type="number" min="0" max="1000" value="" placeholder="0" required></div>
<div class="input-group"><label>Erros (E)</label><input name="wrong" type="number" min="0" max="1000" placeholder="0" required></div>
<div class="input-group"><label>Em branco (B)</label><input name="blank" type="number" min="0" max="1000" value="0" required></div>
<div class="input-group"><label>Com dúvida (D)</label><input name="doubt" type="number" min="0" max="1000" value="0" required></div>
<div class="input-group"><label>Tempo (min)</label><input name="minutes" type="number" min="0" max="9999" placeholder="Ex.: 35" required></div>
<div class="input-group full"><label>IDs das questões erradas (separados por vírgula)</label><input name="wrongIds" placeholder="Ex.: 123456, 567890"></div>
<div class="input-group full"><label>IDs das questões respondidas com dúvida (podem coincidir com erros)</label><input name="doubtIds" placeholder="Ex.: 135791, 246802"></div>
<div class="input-group full"><label>IDs acertadas ao refazer (opcional, só no modo revisão)</label><input name="correctIds" placeholder="Ex.: 123456, 567890"></div>
<div class="input-group full"><label>Observações do estudo</label><textarea name="notes" rows="2" placeholder="Pegadinhas, dispositivos legais, assuntos recorrentes"></textarea></div>
<div class="between full" style="flex-wrap:wrap"><div class="smalltext muted"><span class="smalltext muted">Consulte seu resumo fora da plataforma</span></div><div class="form-actions"><button type="button" class="btn btn-ghost" data-action="close-modal">Cancelar</button><button class="btn btn-teal" type="submit">Salvar bateria e programar SRS</button></div></div></form>`)}
function parseIds(text){return [...new Set(String(text||'').split(/[,;\s]+/).map(x=>x.trim().replace(/^#/,'')).filter(x=>/^[\w.-]{1,42}$/.test(x)))].slice(0,250)}
function ensureTECReview(batch,questionId,label){const id=`tec:${batch.code}:${questionId}`;let old=state.questionReviews.find(x=>x.id===id);const due=advance(batch.date,1),kind=label==='wrong'?'Errei':'Dúvida';const next={id,code:batch.code,questionId,block:batch.block,topic:batch.topic,kind:'tec',url:findBook(batch.code)?.url,front:`Refaça a questão ${questionId} no caderno TEC ${batch.code}.`,back:'Confira o gabarito e justificativa diretamente no TEC.',due,interval:1,lastRating:'again',reviews:old?.reviews||0,lapses:(old?.lapses||0)+(label==='wrong'?1:0),history:old?.history||[],source:'',note:kind};if(old){Object.assign(old,next)}else state.questionReviews.push(next)}
function recordBatch(d){let b=findBook(d.code);if(!b)throw new Error('Código TEC não encontrado no catálogo.');for(let k of ['total','correct','wrong','blank','doubt','minutes']){d[k]=Number(d[k]);if(!Number.isInteger(d[k])||d[k]<0)throw new Error(`Valor inválido para ${k}.`)}if(d.total<1||d.total>1000)throw new Error('Quantidade deve estar entre 1 e 1000.');if(d.correct+d.wrong+d.blank!==d.total)throw new Error('A soma de acertos, erros e brancos deve ser igual ao total de questões.');if(d.doubt>d.total)throw new Error('Dúvidas não podem exceder o total de questões.');if(!/^\d{4}-\d{2}-\d{2}$/.test(d.date))throw new Error('Data inválida.');d.wrongIds=parseIds(d.wrongIds);d.doubtIds=parseIds(d.doubtIds);d.correctIds=parseIds(d.correctIds);if(d.wrongIds.length>d.wrong)throw new Error('Há mais IDs de erro do que a quantidade de erros informada.');if(d.doubtIds.length>d.doubt)throw new Error('Há mais IDs de dúvida do que a quantidade de dúvidas informada.');if(d.correctIds.length>d.correct)throw new Error('Há mais IDs acertados do que o total de acertos.');d.mode=d.mode==='redo'?'redo':'nova';d.block=b.block;d.topic=b.topic;d.id=`B-${Date.now()}-${Math.floor(Math.random()*1000)}`;state.batches.push(d);
  // A mesma questão pode constar em erradas e dúvidas. A classificação de erro prevalece.
  for(let id of d.wrongIds)ensureTECReview(d,id,'wrong');for(let id of d.doubtIds)if(!d.wrongIds.includes(id))ensureTECReview(d,id,'doubt');
  if(d.mode==='redo')for(let id of d.correctIds){if(d.wrongIds.includes(id)||d.doubtIds.includes(id))continue;let x=state.questionReviews.find(q=>q.id===`tec:${d.code}:${id}`);if(x)gradeReview(x,'easy',d.date,false)}
  let missing=Math.max(0,d.wrong-d.wrongIds.length)+Math.max(0,d.doubt-d.doubtIds.length)+d.blank;
  if(missing>0){let review={id:`tec-lote:${d.id}`,code:d.code,block:d.block,topic:d.topic,kind:'tec-batch',url:b.url,front:`Refaça os erros, omissões e dúvidas sem ID individual informado no caderno TEC ${d.code}.`,back:'Use o gabarito do TEC. Informe os IDs em próximas sessões para aprimorar a fila.',due:advance(d.date,1),interval:1,history:[],lastRating:'again',reviews:0,lapses:1};state.questionReviews.push(review)}
  let t=findTopic(b.topicIds[0]);if(t&&t.status==='not-started')t.status='in-progress';persist();return d}
function gradeReview(x,r,date=nowDay(),rerender=true){let current=n(x.interval)||1;if(r==='again'){x.interval=1;x.lapses=n(x.lapses)+1}else if(r==='hard')x.interval=Math.max(2,Math.round(current*1.5));else x.interval=Math.max(4,Math.round(current*2));x.interval=Math.min(x.interval,28);x.lastRating=r;x.reviews=n(x.reviews)+1;x.history=x.history||[];x.history.push({date,rating:r});x.due=advance(date,x.interval);if(rerender){persist();ui.activeReview=null;ui.revealed=false;render();toast(r==='again'?'Cartão reprogramado para D+1':'Revisão registrada com sucesso.')}}
function recordQuiz(q,a,doubt){let correct=a===q.a;const obj={id:`QA-${Date.now()}`,questionId:q.id,block:q.block,topic:q.topic,date:nowDay(),answer:a,key:q.a,correct,doubt};state.quizAttempts.push(obj);if(!correct||doubt){let id=`quiz:${q.id}`;let found=state.cards.find(x=>x.id===id);let review={id,block:q.block,topic:q.topic,kind:'ce',front:q.q,back:q.a==='C'?'Certo':'Errado',explain:q.why,due:advance(nowDay(),1),interval:1,lastRating:'again',reviews:0,lapses:correct?0:1,history:[],source:'Questão autoral CGU Atlas'};if(found)Object.assign(found,review);else state.cards.push(review)}persist();return obj}
function exportState(){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json;charset=utf-8'});downloadBlob(blob,`CGU_ATLAS_backup_${nowDay()}.json`);state.settings.lastBackup=nowDay();persist();toast('Backup JSON exportado.')}
function downloadBlob(blob,name){let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1200)}
function reportText(r){let out=[`CGU Atlas — Relatório ${r.start} a ${r.day}`,`Novas questões: ${r.total}; acertos: ${r.correct}; erros: ${r.wrong}; brancos: ${r.blank}; dúvidas: ${r.uncertain}; líquida: ${r.net}; tempo: ${r.minutes} min.`,"Cadernos prioritários por desempenho:" ];for(let b of r.worst)out.push(`- ${b.code}: ${b.correct}/${b.total} acertos, ${b.wrong} erros, ${b.doubt} dúvidas`);out.push('Próximos passos: revisar vencidos; refazer erradas e dúvidas; treinar P3 avaliação causal, processo sancionador, AFO/CASP, amostragem.','Os dados desta mensagem são locais; não há sincronização automática com ChatGPT/TEC.');return out.join('\n')}
function copyText(str){let done=()=>toast('Texto copiado. Cole na conversa do projeto CGU.');if(navigator.clipboard&&window.isSecureContext)navigator.clipboard.writeText(str).then(done).catch(()=>fallback());else fallback();function fallback(){let t=document.createElement('textarea');t.value=str;t.style.position='fixed';t.style.opacity=0;document.body.append(t);t.select();let ok=document.execCommand('copy');t.remove();if(ok)done();else toast('Cópia não disponível no navegador. Exportar o backup é uma alternativa.')}}
function chatSummary(){let recent=state.batches.slice(-6);let str=`CGU ATLAS — REGISTRO PARA O PROJETO CGU 2026\nData: ${nowDay()}\n${state.baseline?.diagnostic?`Diagnóstico local: ${state.baseline.diagnostic.net}/${state.baseline.diagnostic.max} pontos.`:"Nenhum diagnóstico local registrado."}\nRevisões vencidas atualmente: ${reviewDue()}\n`;if(recent.length)str+='Baterias TEC registradas:\n'+recent.map(b=>`TEC ${b.code} | modo=${b.mode} | data=${b.date} | total=${b.total} | C=${b.correct} | E=${b.wrong} | B=${b.blank} | duvidas=${b.doubt} | erradas=${b.wrongIds.join(',')} | duvidosas=${b.doubtIds.join(',')} | tempo=${b.minutes}min`).join('\n');else str+='Nenhuma bateria TEC nova foi informada ao aplicativo.\n';let errors=state.questionReviews.filter(q=>q.due<=nowDay()).map(x=>x.id);str+='\nQuestões em revisão: '+(errors.join(', ')||'nenhuma')+'\nUse esses dados para ajustar o estudo da CGU, sem misturar a Receita Federal.';return str}
function pasteModal(){modal(`<div class="modal-head"><div><span class="eyebrow">IMPORTAR RESULTADO TEXTUAL</span><h2>Colar registro TEC</h2><p class="page-sub">Cole o formato usado na conversa do ChatGPT. Os números serão validados.</p></div><button class="close" data-action="close-modal">×</button></div><form id="paste-form"><div class="input-group"><label>Exemplo: TEC Q4pAfd | modo=nova | total=20 | C=14 | E=4 | B=2 | duvidas=3 | erradas=123,456 | duvidosas=987 | tempo=32min</label><textarea name="raw" rows="5" placeholder="Cole seu registro aqui" required></textarea></div><div class="form-actions" style="margin-top:14px"><button type="button" class="btn btn-ghost" data-action="close-modal">Cancelar</button><button class="btn btn-teal" type="submit">Validar e registrar</button></div></form>`)}
function parseBatchText(raw){let code=raw.match(/\bTEC\s+(Q[\w-]+)/i)?.[1];if(!code)throw new Error('Não encontrei o código TEC. Ex.: TEC Q4pAfd.');let props={};for(let p of raw.split('|').slice(1)){let match=p.trim().match(/^([\wçãúéí]+)\s*=\s*(.*)$/i);if(match)props[match[1].trim().toLowerCase()]=match[2].trim()}let get=(...keys)=>{for(let k of keys)if(props[k]!=null)return props[k];return ''};let t=get('tempo').replace(/min\b/ig,'').trim();return {code,date:get('data')?get('data').split('/').reverse().join('-'):nowDay(),mode:/refazer|redo|revis/.test(get('modo').toLowerCase())?'redo':'nova',total:get('total'),correct:get('c'),wrong:get('e'),blank:get('b'),doubt:get('duvidas','dúvidas','d'),minutes:t||0,wrongIds:get('erradas','ids_erradas'),doubtIds:get('duvidosas','ids_duvidosas'),correctIds:get('acertadas'),notes:get('obs','observacoes')}}
function calendarEdit(id){let p=state.plan.find(x=>x.id===id);if(!p)return;modal(`<div class="modal-head"><div><span class="eyebrow">CALENDÁRIO · EDIÇÃO</span><h2>Reprogramar missão</h2><p class="page-sub">As alterações são salvas no calendário local</p></div><button class="close" data-action="close-modal">×</button></div><form class="form-grid" id="calendar-form"><input type="hidden" name="id" value="${esc(id)}"><div class="input-group"><label>Data</label><input required type="date" name="date" value="${esc(p.date)}"></div><div class="input-group"><label>Minutos realizados</label><input type="number" min="0" max="900" name="minutes" value="${n(p.actualMinutes)}"></div><div class="input-group"><label>Estado</label><select name="done"><option value="0" ${!p.done?'selected':''}>Pendente</option><option value="1" ${p.done?'selected':''}>Concluída</option></select></div><div class="input-group full"><label>Foco da missão</label><input name="title" value="${esc(p.title)}" required></div><div class="input-group full"><label>Meta observável</label><textarea name="target">${esc(p.target)}</textarea></div><div class="full form-actions"><button type="button" class="btn btn-ghost" data-action="close-modal">Cancelar</button><button class="btn btn-teal" type="submit">Salvar missão</button></div></form>`)}
document.addEventListener('click',e=>{
  if(e.target.id==='menu-toggle'){e.preventDefault();$('#sidebar').classList.toggle('open');return}
  if(e.target.id==='backup-top'||e.target.closest('#backup-top')){e.preventDefault();exportState();return}
  const nv=e.target.closest('[data-view]');if(nv){e.preventDefault();toggleNav(nv.dataset.view);return}
  const bt=e.target.closest('[data-action]');if(!bt)return;e.preventDefault();let action=bt.dataset.action;
  try{
    switch(action){
      case 'open-book':openBookForm(bt.dataset.code);break;
      case 'tec-page':ui.tecPage=Math.max(0,n(bt.dataset.page));render();break;
      case 'tec-paste':pasteModal();break;
      case 'close-modal':closeModal();break;
      case 'select-review':ui.activeReview=bt.dataset.id;ui.revealed=false;render();break;
      case 'review-reveal':ui.revealed=true;render();break;
      case 'review-grade':{let c=[...state.cards,...state.questionReviews].find(x=>x.id===bt.dataset.id);if(c)gradeReview(c,bt.dataset.grade);break}
      case 'quiz-choose':ui.quizAnswer=bt.dataset.answer;render();break;
      case 'quiz-submit':{const q=questionBank.find(x=>x.id===ui.quizQuestion);if(!q||!ui.quizAnswer||ui.quizShow)return;recordQuiz(q,ui.quizAnswer,ui.quizDoubt);ui.quizShow=true;render();toast('Resposta registrada.');break}
      case 'quiz-next':{ui.quizQuestion=pickQuestion()?.id||null;ui.quizAnswer=null;ui.quizDoubt=false;ui.quizShow=false;render();break}
      case 'calendar-edit':calendarEdit(bt.dataset.id);break;
      case 'report-download':{let r=weeklyStats(ui.reportDay);downloadBlob(new Blob([reportText(r)],{type:'text/plain;charset=utf-8'}),`CGU_ATLAS_relatorio_${r.day}.txt`);break}
      case 'copy-chat':copyText(ui.view==='report'?reportText(weeklyStats(ui.reportDay)):chatSummary());break;
      case 'export':exportState();break;
      case 'import':$('#import-file').click();break;
      case 'reset':if(confirm('Restaurar os registros iniciais? Todos os dados locais adicionados serão apagados. Exporte um backup antes.')){state=loadFresh();persist();ui.quizQuestion=null;render();toast('Dados iniciais restaurados.')}break;
      case 'topic-status':{let t=findTopic(bt.dataset.id);if(t){t.status=t.status==='not-started'?'in-progress':t.status==='in-progress'?'done':'not-started';persist();render();toast('Cobertura do tópico atualizada.')}break}
    }
  }catch(err){console.error(err);toast(err.message||'Não foi possível concluir a ação.')}
});
document.addEventListener('submit',e=>{
  const f=e.target;const formId=f.getAttribute('id');if(!['tec-form','study-form','settings-form','paste-form','calendar-form'].includes(formId))return;e.preventDefault();const v=Object.fromEntries(new FormData(f).entries());try{
    if(formId==='tec-form'){
      let d=recordBatch({...v});closeModal();ui.view='tec';render();const s=batchScore(d);toast(`Bateria ${d.code}: ${s.net}/${s.max} pontos. Revisões agendadas.`);copyText(`CGU 2026 — Registro TEC ${d.code} | modo=${d.mode} | data=${d.date} | total=${d.total} | C=${d.correct} | E=${d.wrong} | B=${d.blank} | duvidas=${d.doubt} | erradas=${d.wrongIds.join(',')} | duvidosas=${d.doubtIds.join(',')} | tempo=${d.minutes}min | nota líquida=${s.net}/${s.max}. Integre ao histórico da CGU e programe SRS.`);
    }else if(formId==='paste-form'){
      let d=recordBatch(parseBatchText(v.raw));closeModal();ui.view='tec';render();toast(`Registro TEC ${d.code} importado do texto.`)
    }else if(formId==='study-form'){
      if(n(v.minutes)<1||n(v.minutes)>900)throw new Error('Minutos fora do intervalo permitido.');state.studyLogs.push({id:`T-${Date.now()}`,date:v.date,topic:v.topic,minutes:n(v.minutes)});persist();render();toast('Tempo de estudo salvo.');
    }else if(formId==='settings-form'){
      state.settings.dailyMinutes=clamp(n(v.daily),20,900);state.settings.weekHours=clamp(n(v.weekly),1,90);persist();render();toast('Disponibilidade semanal atualizada.');
    }else if(formId==='calendar-form'){
      let p=state.plan.find(x=>x.id===v.id);if(!p)throw new Error('Missão não encontrada.');p.date=v.date;p.title=v.title;p.target=v.target;p.done=v.done==='1';p.actualMinutes=n(v.minutes);persist();closeModal();render();toast('Calendário atualizado.');
    }
  }catch(err){console.error(err);alert(`Não foi possível registrar: ${err.message}`)}
});
document.addEventListener('change',e=>{let x=e.target;if(x.id==='tec-block'){ui.tecFilter=x.value;ui.tecPage=0;render()}else if(x.id==='tec-sort'){ui.tecSort=x.value;ui.tecPage=0;render()}else if(x.id==='topic-block'){ui.topicFilter=x.value;render()}else if(x.id==='quiz-block'){ui.quizBlock=x.value;ui.quizQuestion=null;ui.quizAnswer=null;ui.quizDoubt=false;ui.quizShow=false;render()}else if(x.id==='quiz-mode'){ui.quizMode=x.value;ui.quizQuestion=null;ui.quizAnswer=null;ui.quizDoubt=false;ui.quizShow=false;render()}else if(x.id==='quiz-doubt'){ui.quizDoubt=x.checked}else if(x.id==='report-date'){ui.reportDay=x.value;render()}});
let searchTimeout;document.addEventListener('input',e=>{let x=e.target;if(x.id==='tec-search'||x.id==='topic-search'){const isTopic=x.id==='topic-search';ui[isTopic?'topicSearch':'tecSearch']=x.value;clearTimeout(searchTimeout);const len=x.selectionStart;searchTimeout=setTimeout(()=>{render();let inp=$(isTopic?'#topic-search':'#tec-search');if(inp){inp.focus();try{inp.setSelectionRange(len,len)}catch(e){}}},220)}});
$('#import-file').addEventListener('change',e=>{let file=e.target.files?.[0];if(!file)return;let r=new FileReader();r.onload=()=>{try{let val=JSON.parse(r.result);if(val.app!=='CGU Atlas'||!Array.isArray(val.books)||!Array.isArray(val.cards)||!Array.isArray(val.topics)||!Array.isArray(val.batches))throw new Error('O arquivo não é um backup CGU Atlas válido.');if(!confirm(`Restaurar backup com ${val.batches.length} baterias? Os dados atuais serão substituídos.`))return;state=prunePrivateDocLinks(val);state.baseline=state.baseline||{xp:0};persist();ui.quizQuestion=null;ui.view='dashboard';render();toast('Backup restaurado com sucesso.')}catch(err){alert('Falha ao importar JSON: '+err.message)}finally{e.target.value=''}};r.readAsText(file,'utf-8')});
// Keep links and forms inert until the page is fully initialized.
render();
})();
